ALTER TABLE revocation_journal_records DROP CONSTRAINT ck_revocation_journal_records_kind_valid;
ALTER TABLE revocation_journal_records ADD CONSTRAINT ck_revocation_journal_records_kind_valid CHECK (kind IN ('genesis', 'revocation', 'recovery_begin', 'recovery_end', 'review_closure', 'session_revocation', 'reset_token_closure', 'invitation_closure'));
ALTER TABLE revocation_journal_records DROP CONSTRAINT ck_revocation_journal_records_session_matches_body;
ALTER TABLE revocation_journal_records ADD CONSTRAINT ck_revocation_journal_records_session_matches_body CHECK (CASE WHEN kind = 'session_revocation' THEN (session_id::text IS NOT DISTINCT FROM (line::jsonb #>> '{body,session_id}')) AND (session_user_id::text IS NOT DISTINCT FROM (line::jsonb #>> '{body,user_id}')) AND (line::jsonb ->> 'kind' IS NOT DISTINCT FROM kind) AND COALESCE((line::jsonb #>> '{body,reason_code}') IN ('logout', 'replaced', 'user_revoked', 'password_reset', 'user_disabled'), false) AND COALESCE(length(line::jsonb #>> '{body,revoked_at}') > 0, false) ELSE true END);
ALTER TABLE revocation_journal_records DROP CONSTRAINT ck_revocation_journal_records_reset_matches_body;
ALTER TABLE revocation_journal_records ADD CONSTRAINT ck_revocation_journal_records_reset_matches_body CHECK (CASE WHEN kind = 'reset_token_closure' THEN (reset_token_id::text IS NOT DISTINCT FROM (line::jsonb #>> '{body,token_id}')) AND (reset_token_user_id::text IS NOT DISTINCT FROM (line::jsonb #>> '{body,user_id}')) AND (reset_end_kind IS NOT DISTINCT FROM (line::jsonb #>> '{body,end_kind}')) AND (reset_reason_code IS NOT DISTINCT FROM (line::jsonb #>> '{body,reason_code}')) AND (reset_ended_at IS NOT DISTINCT FROM (line::jsonb #>> '{body,ended_at}')::timestamptz) AND (line::jsonb ->> 'kind' IS NOT DISTINCT FROM kind) AND COALESCE((reset_end_kind = 'consumed' AND reset_reason_code IN ('password_reset', 'legacy_consumed')) OR (reset_end_kind = 'revoked' AND reset_reason_code IN ('reset_replaced', 'reset_completed', 'user_disabled', 'legacy_revoked')), false) ELSE true END);
ALTER TABLE password_reset_tokens DROP CONSTRAINT ck_password_reset_tokens_closure_reason_valid;
ALTER TABLE password_reset_tokens ADD CONSTRAINT ck_password_reset_tokens_closure_reason_valid CHECK (closure_reason IS NULL OR (used_at IS NOT NULL AND closure_reason IN ('password_reset', 'legacy_consumed')) OR (revoked_at IS NOT NULL AND closure_reason IN ('reset_replaced', 'reset_completed', 'user_disabled', 'legacy_revoked')));
ALTER TABLE sessions DROP CONSTRAINT ck_sessions_revoked_reason_valid;
ALTER TABLE sessions ADD CONSTRAINT ck_sessions_revoked_reason_valid CHECK (revoked_reason IS NULL OR revoked_reason IN ('logout','replaced','user_revoked','password_reset','user_disabled'));